save(99,dict(paragraphs=["Gopa Bhattacharjee is a bilingual poet and entrepreneur from Kolkata. Her English collections include Unturned Verses and Thirty Birds. Her literary activity also includes interviewing fellow writers: in IPPL Journal, she speaks with Lopamudra Banerjee about poetry, collaboration and translation.","Her poems in Kabita Live explore moments when an inner voice confronts loss or resistance. ‘Transient’ brings sleeplessness, memory and winter into a brief recognition of impermanence. ‘The Soliloquy’ draws on Shakespearean figures and a phoenix image to move from betrayal and doubt towards renewed courage."],sources=[source('Setu — Gopa Bhattacharjee, December2022','https://www.setumag.com/2022/12/gopa-bhattacharjee-childrens-world.html',['Kolkata upbringing; bilingual poet and entrepreneur; Unturned Verses and Thirty Birds.']),source('IPPL Journal — Interview with Lopamudra Banerjee, April2024','https://ippljournal.org/issue-5-april-2024/interview-of-lopamudra-banerjee/',['Gopa credited interviewer; matching biography and books.'])],identity_match='Kolkata, entrepreneurship and two distinctive books agree with captured note and journal contributor biographies.',poems_read=[dict(id=69,title='Transient',basis='Full original read: sleeplessness, dream and winter personified, lost closeness and impermanence.'),dict(id=770,title='THE SOLILOQUY',basis='Full original read: stripped plumage, betrayed Julius, Hamlet and Lear allusions, phoenix recovery. Shakespeare quotations not reused as writer’s own quote.')],limitations=['Event appearances and film claims not expanded without organizer/production verification.','No current total asserted; later collaborative book noted in source but omitted to keep concise.','No verified direct book product URL found; no shelf added.'],next_action='Independent author/editor review; verify preferred book links.'))
